// const item = $input.first().json;
const item = $('When Executed by Another Workflow').first().json;
const branch = item.selectedBranch;
const wa = item.wa_payload;
const msg = wa.messages[0];
const contact = wa.contacts[0];
const first_message = $('When Executed by Another Workflow').first().json.first_message
const msgType = msg.type;
const sessionKey = $('SetUserSession').first().json.session_key

const customerData = item.customerData


const userSession = JSON.parse($input.first().json.userSession)


const caption = msgType === 'image' ? msg['image'].caption || null
    : msgType === 'video' ? msg['video'].caption || null
    : msgType === 'document' ? msg['document'].caption || null
    : null;

let mediaId = null;

if (msgType === 'image') mediaId = msg['image'].id;

else if (msgType === 'audio') mediaId = msg['audio'].id;

else if (msgType === 'video') mediaId = msg['video'].id;

else if (msgType === 'document') mediaId = msg['document'].id;


  return [{
    json: {
      customerPhone: msg.from,
      customerName: customerData?.attributes?.customerName || contact.profile.name,
      waId: contact.wa_id,

      branchCode: userSession.preferredBranchCode || 'Empty',
      branchName: userSession.preferredBranchName || 'Empty',
      sessionKey: sessionKey,
      messageId: msg.id,
      messageType: msg.type,
      timestamp: msg.timestamp,
      first_message: JSON.stringify(first_message) || null,
      textBody: msg['text']?.body || null,
      caption: caption,
      audioData: msg['audio'] || null,
      imageData: msg['image'] || null,
      locationData: msg['location'] || null,
      videoData: msg['video'] || null,
      documentData: msg['document'] || null,
      mediaId: mediaId,

      phoneNumberId: wa.metadata.phone_number_id,
      displayPhoneNumber: wa.metadata.display_phone_number
    }
  }];

const originalPayload = $("InputNormalizer").first().json
const messageType = originalPayload.messageType
let processedMessage = ''
let additionalSystemInstruction = ''

// tambahan: buat nyimpen info validasi damage detection (khusus messageType image)
let damageValidationPassed = null
let damageValidationFlags = []

if(messageType === 'text') {
  processedMessage = originalPayload.textBody || ''
} else if (messageType === 'image') {
  const analysis = $input.first().json
  const imageDesc = analysis.rawText || '';
  const caption = originalPayload.caption || '';
  processedMessage = caption
      ? `[Pesan customer: "${caption}"]\n[Deskripsi gambar: ${imageDesc}]`
      : `[Customer mengirim gambar]\n[Deskripsi gambar: ${imageDesc}]`;

  damageValidationPassed = analysis.validation_passed ?? null
  damageValidationFlags = analysis.validation_flags ?? []
} else if (messageType === 'audio') {
  const transcription = $input.first().json
  processedMessage = transcription.content?.parts?.[0]?.text || '';
} else if(messageType === 'interactive' || messageType === 'button') {
  processedMessage = $input.first().json.proccessMessage
  additionalSystemInstruction = $input.first().json.additionalSystemInstruction
} else if (messageType === 'location') {
  const locationData = $input.first().json;
  const latitude = locationData.latitude || '';
  const longitude = locationData.longitude || '';
  processedMessage = `Customer shared their location: Latitude ${latitude}, Longitude ${longitude}. Refer to previous messages to determine the context  
  of this location. Based on the conversation history, use these coordinates to either: (1) call the Branch Recommendation tool to find nearby Auto2000 branches, or
   (2) call the Trigger Transaction tool to send the registration form for Toyota Home Service (THS).`;
} else {
  processedMessage = 'Tipe pesan tidak didukung'
}

return [{
  json: {
      message: processedMessage,
      messageType: messageType,
      routeTo: messageType === 'image' ? 'BP_AGENT' : 'CLASSIFIER_AGENT',
      customerPhone: originalPayload.customerPhone,
      customerName: originalPayload.customerName,
      waId: originalPayload.waId,
      sessionId: originalPayload.sessionKey,
      branchCode: originalPayload.branchCode,
      branchName: originalPayload.branchName,
      messageId: originalPayload.messageId,
      timestamp: originalPayload.timestamp,
      phoneNumberId: originalPayload.phoneNumberId,
      displayPhoneNumber: originalPayload.displayPhoneNumber,
      caption: originalPayload.caption || '',
      hasMedia: ['image', 'audio', 'video'].includes(messageType),
      additionalSystemInstruction: additionalSystemInstruction,
      latitude: messageType === 'location' ? $input.first().json.latitude || '' : '',
      longitude: messageType === 'location' ? $input.first().json.longitude || '' : '',
      address: messageType === 'location' ? $input.first().json.address || '' : '',
      // opsional: info validasi damage detection, buat tracking/audit internal
      damageValidationPassed: damageValidationPassed,
      damageValidationFlags: damageValidationFlags
  }
}]

const msg = $('InputNormalizer').first().json;
return [{
  json: {
    latitude: msg.locationData?.latitude || "",
    longitude: msg.locationData?.longitude || "",
    address: (msg.locationData?.address || "").slice(0, 600),
    keyword: "",
    isoCodeCity: ""
  }
}];

