function tryGet(getter) {
  try {
    return getter();
  } catch (e) {
    return null;
  }
}

let result =
  tryGet(() => $('BP Consult Agent').first().json.output) ||
  tryGet(() => $('Booking').first().json.output) ||
  tryGet(() => $('TestDrive').first().json.output) ||
  tryGet(() => $('ProductKnowledge').first().json.output) ||
  tryGet(() => $('General').first().json.output) ||
  { response: 'Mohon maaf, terjadi kendala pada sistem kami. Silakan coba lagi.', already_sent_wa: false };

return [{ json: result }];

return [{
  json: {
    response: "Mohon maaf Bapak/Ibu, saat ini sistem kami sedang mengalami gangguan teknis. Tim kami akan segera membantu Bapak/Ibu. Apakah Bapak/Ibu berkenan kami hubungkan dengan Service Advisor BP secara langsung? 🙏",
    already_sent_wa: false
  }
}];

const existing = $('GetImgBuffer').first().json.imgBuffer;
const newMessage = $('MergeItem').first().json.message;
const data = $('MergeItem').first().json;

let isRetry = false;
try {
  const retryData = $('GetRetryFlag').first().json.imgRetry;
  isRetry = retryData === 'true';
} catch(e) {
  isRetry = false;
}

if (isRetry) {
  if (existing) {
    return [{ json: { ...data, message: existing, ready: 'process' } }];
  } else {
    return [{ json: { ...data, ready: 'stop' } }];
  }
} else if (existing) {
  const combined = existing + "\n\n---\n\n" + newMessage;
  return [{ json: { ...data, message: combined, ready: 'process' } }];
} else {
  return [{ json: { ...data, message: newMessage, ready: 'wait' } }];
}

for (const item of $input.all()) {
  let dataSebelumnya = item.json;                 // classifier output: { output: { category, language } }
  let dataMergeItem  = $('MergeItem').first().json;
  item.json = {
    ...dataSebelumnya,
    ...dataMergeItem,
    language: dataSebelumnya?.output?.language || 'id',   // <-- the missing line
  };
}
return $input.all();

const item = $input.first().json;
const output = item.output || {};
const response = output.response || '';
const alreadySentWa = output.already_sent_wa === true;
const steps = item.intermediateSteps || [];

// Ambil semua nama tool yang beneran dipanggil
const calledTools = steps.map(s => s?.action?.tool || '').filter(Boolean);

const toolCalled = (name) => calledTools.includes(name);

// ── Cek per tool ──────────────────────────────────────────────

// 1. Send Branch Selection Form
const claimedBranchForm = alreadySentWa;
const actuallySentBranchForm = toolCalled('Call_Send_Select_Branch_Tool');

// 2. Trigger Transaction  
const actuallyTriggered = toolCalled('Call_Trigger_Transaction');

// 3. Dispatcher — cek dari teks response
const DISPATCH_PHRASES = [
  'sudah menghubungkan',
  'telah menghubungkan', 
  'sudah kami hubungkan',
  'sudah terhubung',
];
const claimedDispatch = DISPATCH_PHRASES.some(p =>
  response.toLowerCase().includes(p)
);
const actuallyDispatched = toolCalled('Call_Dispatcher');

// ── Evaluasi ──────────────────────────────────────────────────

const hallucinations = [];

if (claimedBranchForm && !actuallySentBranchForm && !actuallyTriggered) {
  hallucinations.push('send_branch_form');
}
if (claimedDispatch && !actuallyDispatched) {
  hallucinations.push('dispatcher');
}

const isHallucination = hallucinations.length > 0;
const retryCount = item.retryCount || 0;
const MAX_RETRY = 2;

if (isHallucination && retryCount < MAX_RETRY) {
  return [{
    json: {
      hallucination: true,
      hallucination_types: hallucinations,
      retryCount: retryCount + 1,
      retryMessage: `[SYSTEM OVERRIDE: The following tools were claimed but NOT actually called: ${hallucinations.join(', ')}. You MUST call the actual tool in this turn. Do NOT write a response claiming the action was done without calling the tool first.]`,
      output,
      called_tools: calledTools
    }
  }];
}

if (isHallucination && retryCount >= MAX_RETRY) {
  // Max retry reached → fallback message
  return [{
    json: {
      hallucination: false,
      maxRetryReached: true,
      called_tools: calledTools,
      output: {
        ...output,
        response: 'Mohon maaf, Bapak/Ibu 🙏 Terjadi kendala pada sistem kami saat ini. Silakan coba kembali beberapa saat lagi.',
        already_sent_wa: false
      }
    }
  }];
}

// Normal — semua sesuai
return [{
  json: {
    hallucination: false,
    maxRetryReached: false,
    called_tools: calledTools,
    output
  }
}];

const rawText = $input.item.json.content.parts[0].text;
const currentRetry = $input.item.json.retryCount ?? 0;

// --- Cek dulu kasus non-mobil / tidak relevan ---
if (rawText.includes("BUKAN MOBIL") || rawText.includes("TIDAK RELEVAN")) {
  return {
    json: {
      rawText,
      vehicle_check: rawText.includes("BUKAN MOBIL") ? "BUKAN_MOBIL" : "TIDAK_RELEVAN",
      damages: [],
      validation_passed: true,
      validation_flags: [],
      shouldRetry: false,
      retryCount: currentRetry,
      retry_feedback: null
    },
    binary: $input.item.binary
  };
}

// --- Cek dulu kasus foto terlalu dekat / tidak bisa nentuin sisi kendaraan ---
if (rawText.includes("Foto terlalu dekat")) {
  return {
    json: {
      rawText,
      vehicle_check: "OK",
      orientation_uncertain: true,
      damages: [],
      validation_passed: true,
      validation_flags: [],
      shouldRetry: false,
      retryCount: currentRetry,
      retry_feedback: null
    },
    binary: $input.item.binary
  };
}

// --- Cek dulu kasus "tidak ada kerusakan" ---
const noDamagePatterns = [
  /tidak ada kerusakan/i,
  /tidak ditemukan kerusakan/i,
  /no damage/i,
  /kondisi.*mulus/i,
  /tidak terdapat kerusakan/i
];
const isNoDamage = noDamagePatterns.some(p => p.test(rawText));

if (isNoDamage) {
  const vehicleMatch = rawText.match(/Identifikasi kendaraan[:\s]*([^\n.]+)/i);

  return {
    json: {
      rawText,
      vehicle_check: "OK",
      no_damage: true,
      vehicle_identification: vehicleMatch?.[1]?.trim() || null,
      damages: [],
      validation_passed: true,
      validation_flags: [],
      shouldRetry: false,
      retryCount: currentRetry,
      retry_feedback: null
    },
    binary: $input.item.binary
  };
}

// --- Extract shot type / hood direction / visible side ---
const shotTypeMatch = rawText.match(/CAMERA ANGLE[^\n]*\n?[:\s]*([^\n]+)/i)
  || rawText.match(/kamera[:\s]+([^\n]+)/i);

const hoodMatch = rawText.match(/hood[^\n]*(?:point|arah|mengarah)[^\n]*?(image-left|image-right|kiri|kanan|toward camera|away from camera|ke arah kamera|menjauhi kamera)/i);

const visibleSideMatch = rawText.match(/Visible side is[:\s]*\**\s*(LH|RH)/i);

const shot_type = shotTypeMatch?.[1]?.trim() || null;
const hood_direction = hoodMatch?.[1]?.trim() || null;
const visible_side = visibleSideMatch?.[1]?.toUpperCase() || null;

// --- Extract semua panel yang dilaporkan ---
const panelRegex = /🔧\s*Panel:\s*([^\|]+)\|\s*📍\s*Lokasi:\s*([^\|]+)\|\s*🛠\s*Kerusakan:\s*([^\|]+)\|\s*⚠️\s*Severity:\s*([^\n]+)/gi;

let damages = [];
let match;
while ((match = panelRegex.exec(rawText)) !== null) {
  damages.push({
    panel: match[1].trim().toLowerCase(),
    lokasi: match[2].trim(),
    kerusakan: match[3].trim().toLowerCase(),
    severity: match[4].trim().toLowerCase()
  });
}

if (damages.length === 0) {
  return {
    json: {
      rawText,
      vehicle_check: "OK",
      no_damage: true,
      shot_type,
      hood_direction,
      visible_side,
      damages: [],
      validation_passed: true,
      validation_flags: [],
      shouldRetry: false,
      retryCount: currentRetry,
      retry_feedback: null
    },
    binary: $input.item.binary
  };
}

// --- Validasi geometris (hanya jalan kalau memang ada damages) ---
const lhOnlyPanels = ["fender kiri", "pintu depan kiri", "pintu belakang kiri", "quarter panel kiri"];
const rhOnlyPanels = ["fender kanan", "pintu depan kanan", "pintu belakang kanan", "quarter panel kanan"];

let flags = [];

const hoodNormalized = (hood_direction || "").toLowerCase();
const isHoodLeft = hoodNormalized.includes("image-left") || hoodNormalized === "kiri";
const isHoodRight = hoodNormalized.includes("image-right") || hoodNormalized === "kanan";

let expected_visible_side = null;
if (isHoodLeft) expected_visible_side = "LH";
if (isHoodRight) expected_visible_side = "RH";

if (expected_visible_side && visible_side && expected_visible_side !== visible_side) {
  flags.push(`Hood/side mismatch: hood_direction=${hood_direction} seharusnya visible_side=${expected_visible_side}, tapi Gemini jawab visible_side=${visible_side}`);
}

if (visible_side === "LH") {
  damages.forEach(d => {
    if (rhOnlyPanels.includes(d.panel)) {
      flags.push(`Side mismatch: visible_side=LH tapi panel=${d.panel} (RH)`);
    }
  });
}
if (visible_side === "RH") {
  damages.forEach(d => {
    if (lhOnlyPanels.includes(d.panel)) {
      flags.push(`Side mismatch: visible_side=RH tapi panel=${d.panel} (LH)`);
    }
  });
}

if (!visible_side) {
  flags.push("Parsing gagal: visible_side tidak ditemukan di teks, padahal ada damage terdeteksi");
}

const validation_passed = flags.length === 0;
const shouldRetry = !validation_passed && currentRetry < 1;

return {
  json: {
    rawText,
    vehicle_check: "OK",
    no_damage: false,
    shot_type,
    hood_direction,
    visible_side,
    damages,
    validation_passed,
    validation_flags: flags,
    shouldRetry,
    retryCount: shouldRetry ? currentRetry + 1 : currentRetry,
    retry_feedback: shouldRetry ? flags.join('\n') : null
  },
  binary: $input.item.binary
};
